@startuml

class Customer {
  + name : string
}

class Broker {
  + name : string
}

class Policy {
  + price : float
}

class Contract {
  + offerDate : date
  + signingDate : date
  + billingFrequency : string
}

class ClaimCase {
  + status : string
}

class ClaimReport {
  + reportDate : date
  + content : string
}

class CompensationDecision {
  + eligibleCosts : float
}

class Estimator {
  + name : string
  + expertise : string
}

class AlphaInsurance {}

Customer "0..*" -- "0..1" Broker : is assigned to
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" ClaimCase : files
Contract "1" -- "1" Policy : covers
Contract "1" -- "0..*" ClaimCase : generates
ClaimCase "1" -- "1..*" ClaimReport : is assessed by
ClaimCase "1" -- "0..1" CompensationDecision : results in
Estimator "1..*" -- "*" ClaimReport : issues

AlphaInsurance -- Customer
AlphaInsurance -- Broker
AlphaInsurance -- Estimator
AlphaInsurance -- ClaimCase

@enduml

